import{_ as r,C as i,o as t,c as n,a3 as o,b as d,w as a,a as s,E as l,a4 as m}from"./chunks/framework.CRbjHCyB.js";const A=JSON.parse('{"title":"System Architecture","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"System Architecture | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/architecture"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/architecture"}]]},"headers":[],"relativePath":"catter/design/architecture.md","filePath":"en/catter/design/architecture.md","lastUpdated":1788608469000}'),p={name:"catter/design/architecture.md"};function h(u,e,g,f,b,y){const c=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h1><p>Catter is a build-process interception and analysis tool organized around <strong>runtimes</strong>. A runtime is the mechanism that actually captures process creation: every command invocation made by the build system becomes an event catter can handle, and is executed according to the script&#39;s decision -- run as-is, modified, skipped, or aborted.</p><p>Script authors only need to understand two things:</p><ol><li><strong>What a runtime is, which one the current session uses, and what it supports</strong> -- covered here and in <a href="./runtime">Runtime</a>.</li><li><strong>The lifecycle of four callbacks</strong> -- two at the build level (<code>onStart</code> / <code>onFinish</code>) and two at the command level (<code>onCommand</code> / <code>onExecution</code>).</li></ol><h2 id="the-runtime-abstraction" tabindex="-1">The runtime abstraction <a class="header-anchor" href="#the-runtime-abstraction" aria-label="Permalink to &quot;The runtime abstraction&quot;">​</a></h2><p>&quot;Intercepting process creation&quot; differs greatly in feasibility across platforms: hooks are the most general, but are restricted on some platforms (for example, macOS requires special development entitlements). Catter therefore abstracts capture mechanisms as runtimes. One runtime is one capture implementation, exposed to scripts through a fixed capability description (<code>CatterRuntime</code>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>Runtime type: <code>inject</code> / <code>eslogger</code> / <code>env</code></td></tr><tr><td><code>supportActions</code></td><td>Script actions supported by the current runtime (see Actions below)</td></tr><tr><td><code>supportParentId</code></td><td>Whether captured commands can report a parent command ID (command trees, target trees, etc.)</td></tr></tbody></table><p>The runtime is selected with <code>-m/--mode</code> and defaults to <code>inject</code>. Scripts can inspect the current runtime&#39;s capabilities in the config passed to <code>onStart</code>, so they can be written compatibly across runtimes.</p><p>Today only <code>inject</code> (based on hooks) is implemented; <code>env</code> and <code>eslogger</code> are planned. The principles, platform limitations, and capability differences of each mechanism are covered in <a href="./runtime">Runtime</a>.</p><h2 id="script-lifecycle" tabindex="-1">Script lifecycle <a class="header-anchor" href="#script-lifecycle" aria-label="Permalink to &quot;Script lifecycle&quot;">​</a></h2><p>Scripts interact with catter through four callbacks, forming one complete build session:</p>',11)),(t(),d(m,null,{default:a(()=>[l(c,{id:"mermaid-77",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Script%20as%20User%20script%0A%20%20%20%20participant%20Catter%20as%20catter%20daemon%0A%20%20%20%20participant%20Runtime%20as%20Runtime%20(capture%20mechanism)%0A%20%20%20%20participant%20Build%20as%20Build%20system%0A%0A%20%20%20%20Catter-%3E%3ECatter%3A%20Load%20script%0A%20%20%20%20Catter-%3E%3EScript%3A%20onStart(config)%0A%20%20%20%20Script--%3E%3ECatter%3A%20Return%20(possibly%20modified)%20config%0A%20%20%20%20Catter-%3E%3ERuntime%3A%20Start%20build%20(if%20config.execute)%0A%20%20%20%20loop%20For%20each%20captured%20command%0A%20%20%20%20%20%20%20%20Runtime-%3E%3ECatter%3A%20Command%20event%0A%20%20%20%20%20%20%20%20Catter-%3E%3EScript%3A%20onCommand(ctx)%0A%20%20%20%20%20%20%20%20Script--%3E%3ECatter%3A%20Action%20(skip%20%2F%20drop%20%2F%20abort%20%2F%20modify)%0A%20%20%20%20%20%20%20%20Catter-%3E%3ERuntime%3A%20Execute%20according%20to%20action%0A%20%20%20%20%20%20%20%20Runtime-%3E%3ECatter%3A%20Execution%20result%0A%20%20%20%20%20%20%20%20Catter-%3E%3EScript%3A%20onExecution(ctx)%0A%20%20%20%20end%0A%20%20%20%20Runtime--%3E%3ECatter%3A%20Build%20process%20finished%0A%20%20%20%20Catter-%3E%3EScript%3A%20onFinish(result)%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="build-level-onstart-onfinish" tabindex="-1">Build level: onStart / onFinish <a class="header-anchor" href="#build-level-onstart-onfinish" aria-label="Permalink to &quot;Build level: onStart / onFinish&quot;">​</a></h3><p><strong><code>onStart(config)</code></strong> is called once before the build starts.</p><ul><li>The <code>CatterConfig</code> payload includes: the script path and arguments, the build system command and its working directory, the current runtime capabilities, and catter options (<code>log</code>, <code>stdioMode</code>).</li><li>The script may return a modified config (for example, after parsing its own CLI arguments); returning <code>void</code> means no change.</li><li>Setting <code>config.execute = false</code> prevents catter from launching the build (builtin scripts use this to exit gracefully when argument parsing fails).</li></ul><p><strong><code>onFinish(result)</code></strong> is called once after the build process ends. <code>result</code> is the process result of the build command itself: exit code and captured stdout/stderr. Builtin scripts persist their final output here (for example, the cdb script writes <code>compile_commands.json</code>).</p><h3 id="command-level-oncommand-onexecution" tabindex="-1">Command level: onCommand / onExecution <a class="header-anchor" href="#command-level-oncommand-onexecution" aria-label="Permalink to &quot;Command level: onCommand / onExecution&quot;">​</a></h3><p><strong><code>onCommand(ctx)</code></strong> is called for each captured command before it executes.</p><ul><li><code>ctx.capture</code> is the captured command: working directory, executable, full argument vector, environment, the runtime that captured it, and the parent command ID (if supported).</li><li>Capture can fail (for example, when the runtime cannot resolve the command); <code>ctx.capture</code> is then an <code>Err</code>, and the script decides how to handle it.</li><li>The script chooses an action via <code>ctx.skip()</code> / <code>ctx.drop()</code> / <code>ctx.abort()</code> / <code>ctx.modify(data)</code> / <code>ctx.setAction(action)</code>; if none is chosen, the default is <code>skip</code> (execute as-is).</li><li><code>ctx.ignoreDescendants()</code> prevents all descendant commands of this command from triggering <code>onCommand</code> / <code>onExecution</code>. Combine it with <code>skip</code> to &quot;capture this command but ignore its subtree&quot;.</li></ul><p><strong><code>onExecution(ctx)</code></strong> is called after each command finishes. <code>ctx.result</code> is the command&#39;s exit code and output. Scripts can aggregate statistics or failures here (for example, the cdb script&#39;s <code>--abort-on-command-failure</code>).</p><h2 id="actions-separating-script-semantics-from-execution-mechanics" tabindex="-1">Actions: separating script semantics from execution mechanics <a class="header-anchor" href="#actions-separating-script-semantics-from-execution-mechanics" aria-label="Permalink to &quot;Actions: separating script semantics from execution mechanics&quot;">​</a></h2><p>&quot;How to handle a command&quot; is expressed at two layers in catter:</p><ol><li><strong>Script layer</strong> (what scripts see): <code>skip</code> / <code>drop</code> / <code>abort</code> / <code>modify</code> -- semantic and independent of the mechanism.</li><li><strong>Protocol layer</strong> (what the proxy executes): <code>DROP</code> / <code>INJECT</code> / <code>WRAP</code> -- the concrete execution mechanics.</li></ol><p>The runtime driver maps script-layer actions to protocol-layer actions. The current <code>inject</code> runtime mapping:</p><table tabindex="0"><thead><tr><th>Script action</th><th>Semantics</th><th>Protocol mapping</th></tr></thead><tbody><tr><td><code>skip</code></td><td>Execute as-is, catter does not intervene</td><td><code>INJECT</code> (run with hooks mounted; descendants can still be captured)</td></tr><tr><td><code>drop</code></td><td>Do not execute; return exit code 0</td><td><code>DROP</code></td></tr><tr><td><code>abort</code></td><td>Abort the whole build and report an error</td><td>not implemented yet (see below)</td></tr><tr><td><code>modify</code></td><td>Execute the command with replacement data</td><td><code>INJECT</code> (carrying the modified command)</td></tr></tbody></table><p>Two things are easy to confuse:</p><ul><li><strong><code>skip</code> is not &quot;ignore the whole subtree&quot;</strong>. <code>skip</code> only lets this command run as-is; its descendants are still captured and still trigger callbacks. To skip a subtree, call <code>ctx.ignoreDescendants()</code> explicitly.</li><li><strong>Not every runtime supports every action</strong>. Scripts should check <code>config.runtime.supportActions</code>. For example, <code>inject</code> currently supports <code>[skip, drop, modify]</code>; <code>abort</code> has defined script-layer semantics but is not yet supported by any runtime, and using it will fail.</li></ul><h2 id="components-and-processes" tabindex="-1">Components and processes <a class="header-anchor" href="#components-and-processes" aria-label="Permalink to &quot;Components and processes&quot;">​</a></h2><p>A single <code>catter &lt;script&gt; -- &lt;build command&gt;</code> run involves several processes and components. They are all part of the runtime implementation, and script authors usually do not need to know about them:</p><table tabindex="0"><thead><tr><th>Component</th><th>Role</th></tr></thead><tbody><tr><td><code>catter</code> (daemon)</td><td>Loads and runs the script, owns the JS runtime, receives commands over IPC and returns decisions</td></tr><tr><td><code>catter-proxy</code></td><td>Executes commands and relays IPC; has an injector mode (launching the build) and a wrapper mode (standing in for intercepted commands)</td></tr><tr><td>hook shared library</td><td>The capture carrier of the inject runtime; injected into build processes to intercept process creation</td></tr></tbody></table><blockquote><p>Earlier documentation described these three components as catter&#39;s &quot;three-part architecture&quot;. The current view is one level higher: they are <strong>implementation details of the inject runtime</strong>, and the runtime abstraction itself is the center of the architecture. See <a href="./runtime">Runtime</a> and <a href="./hook-mechanism">Hook mechanism</a>.</p></blockquote><h2 id="js-runtime-model" tabindex="-1">JS runtime model <a class="header-anchor" href="#js-runtime-model" aria-label="Permalink to &quot;JS runtime model&quot;">​</a></h2><p>The JS runtime is single-threaded: script callbacks never run in parallel. The daemon&#39;s I/O (IPC connections, command traffic) is asynchronous and concurrent, but script execution is always serial; scripts holding global state should keep in mind that async callbacks may interleave at <code>await</code> points.</p>',21))])}const C=r(p,[["render",h]]);export{A as __pageData,C as default};
